  "status": "issues",
  "checks": [
    "claim_scope",
    "numeric_bounds"
  ],
  "issues": [
    {
      "category": "scope_expansion",
      "claim_anchor_id": "Cacdd42deaf818ddb1ae8",
      "problem": "主张声称引用 Lal99 数据说明波导型设计在'大角度下保持高效率且无阴影效应'。然而，证据材料（Ee288fda065d3464ca999）明确指出，当纳米柱间距过小时存在电磁耦合，导致在大偏离角（高 NA）和斜入射下效率显著降低；只有在间距处于特定“结构截止”范围内且解耦时，相位才独立于入射角。主张将特定条件下的优势泛化为波导型设计的普遍特性，忽略了材料中强调的间距约束和耦合导致的效率下降风险。",
      "requested_change": "需限定波导型设计在大角度下保持高效率的前提条件（即纳米柱间距需处于结构截止范围内以避免耦合），或删除关于'大角度下'无条件保持高效率的绝对化表述。",
      "evidence_anchor_ids": [
        "Ee288fda065d3464ca999",
        "Ebdc0ffed1c17032ae1a9"
      ]
    },
    {
      "category": "scope_expansion",
      "claim_anchor_id": "Cd07c601e071e191b913d",
      "problem": "主张断言共振型设计（如 Kho16）'在斜入射下存在固有缺陷'。虽然证据材料（E267164303eacce8a60a0, Eaaa333d90b7e0bb44e2b）通过 Dec15 的理论模型证实了反对称模式激发会导致斜入射效率下降，但材料同时也明确指出（Ebf64106c1f812f302afb, Ece465b71d419aa43a9ae）：文中未提供 Kho16 原始论文中关于斜入射效率下降的具体定量实验数据，该机制仅通过 Dec15 模型说明。将理论模型的推论直接作为 Kho16 器件的既定事实陈述，超出了现有证据对具体案例的支持范围。",
      "requested_change": "应明确区分理论机制（基于 Dec15 模型）与具体器件表现（Kho16），指出斜入射缺陷是基于理论模型的预测或机制解释，而非 Kho16 实验中已直接观测并量化的结果。",
      "evidence_anchor_ids": [
        "E267164303eacce8a60a0",
        "Ebf64106c1f812f302afb",
        "Eaaa333d90b7e0bb44e2b"
      ]
    },
    {
      "category": "numeric_bound",
      "claim_anchor_id": "Ce96d81cf6e03308103e2",
      "problem": "主张中提到'NA=0.5 时<5 µm'的视场限制。证据材料（Ea478e1e287c61aa2dec1, E96b1548f09acf438cd96）支持这一数值，但明确指出了该限制的适用条件为'焦距 f = 1 mm'且'路径延迟误差不超过一个波长'。主张中省略了焦距这一关键参数，可能导致读者误以为该视场限制仅由 NA 决定，而实际上它与焦距密切相关（对于不同焦距，线性视场大小会变化）。",
      "requested_change": "在提及'<5 µm'的视场限制时，必须补充说明其对应的焦距条件（如 f=1mm），或明确该数值是针对特定焦距系统的线性尺寸估算，避免将其表述为仅由 NA 决定的通用物理常数。",
      "evidence_anchor_ids": [
        "Ea478e1e287c61aa2dec1",
        "E96b1548f09acf438cd96",
        "E0562db1976d2a7d52855"
      ]
    }
  ]
}

